CREATE TABLE public.action_budgets (user_id uuid NOT NULL, action text NOT NULL, window_start timestamptz NOT NULL, hits integer NOT NULL DEFAULT 0, PRIMARY KEY(user_id,action,window_start));
GRANT ALL ON public.action_budgets TO service_role;
ALTER TABLE public.action_budgets ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_action_budget(_action text,_maximum integer,_seconds integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE slot timestamptz; n integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF; slot=to_timestamp(floor(extract(epoch FROM now())/_seconds)*_seconds); INSERT INTO action_budgets(user_id,action,window_start,hits) VALUES(auth.uid(),_action,slot,1) ON CONFLICT(user_id,action,window_start) DO UPDATE SET hits=action_budgets.hits+1 RETURNING hits INTO n; IF n>_maximum THEN RAISE EXCEPTION 'Limite de ações atingido. Aguarde antes de tentar novamente.'; END IF; END $$;
REVOKE ALL ON FUNCTION public.consume_action_budget(text,integer,integer) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.limit_community_writes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.created_at=now(); IF TG_TABLE_NAME='game_requests' THEN PERFORM consume_action_budget('request',10,86400); ELSE PERFORM consume_action_budget('feedback',30,86400); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.limit_player_plays() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.created_at=now(); PERFORM consume_action_budget('open',1,10); PERFORM consume_action_budget('open_daily',100,86400); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.preserve_request_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.created_at=OLD.created_at; RETURN NEW; END $$;
CREATE TRIGGER preserve_request_date BEFORE UPDATE ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.preserve_request_date();
CREATE OR REPLACE FUNCTION public.limit_social_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM consume_action_budget(TG_TABLE_NAME,30,60); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER rating_budget BEFORE INSERT OR UPDATE OR DELETE ON public.game_ratings FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE TRIGGER vote_budget BEFORE INSERT OR DELETE ON public.request_votes FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE OR REPLACE FUNCTION public.finish_daily_challenge(_run uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r challenge_runs; BEGIN SELECT * INTO r FROM challenge_runs WHERE id=_run AND user_id=auth.uid() FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Partida indisponível'; END IF; IF r.finished_at IS NULL AND (now()-r.started_at>=interval '60 seconds' OR r.day<>(now() AT TIME ZONE 'UTC')::date) THEN UPDATE challenge_runs SET finished_at=now() WHERE id=r.id RETURNING * INTO r; END IF; RETURN jsonb_build_object('done',r.finished_at IS NOT NULL,'step',r.step,'score',r.score); END $$;
REVOKE ALL ON FUNCTION public.finish_daily_challenge(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finish_daily_challenge(uuid) TO authenticated;
CREATE INDEX requests_author_date ON public.game_requests(user_id,created_at DESC);
CREATE INDEX feedback_author_date ON public.game_feedback(user_id,created_at DESC);
CREATE INDEX challenge_user_day ON public.challenge_runs(user_id,day);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_ratings,public.game_requests,public.request_votes,public.player_library TO authenticated;
GRANT SELECT,UPDATE ON public.profiles TO authenticated;
GRANT SELECT,INSERT ON public.game_feedback,public.play_events TO authenticated;
GRANT SELECT ON public.challenge_runs TO authenticated;
GRANT SELECT ON public.game_requests TO anon;
GRANT ALL ON public.profiles,public.game_ratings,public.game_requests,public.request_votes,public.player_library,public.game_feedback,public.play_events,public.challenge_runs,public.rtc_rooms,public.rtc_members,public.rtc_signals TO service_role;